{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-8497ae41ecbde8d1","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Shared-surface enforcement deliverables: a general Implementation epic\n28\t     (null implementation_type) whose TITLE names an enforcement tool (lint\n29\t     rule, CI check, static-analysis check, validation harness, enforcement)\n30\t     that shares its `component` with at least one other non-docs\n31\t     Implementation epic is a work-type extraction — the enforcement work was\n32\t     divided by work-product type instead of per surface. Exempt when the\n33\t     enforcement tool is the component's only implementation work (it is then\n34\t     the deliverable itself, not an extraction).\n35\t\n36\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n37\t\n38\tUsage:\n39\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n40\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n41\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n42\t\"\"\"\n43\t\n44\timport argparse\n45\timport os\n46\timport re\n47\timport sys\n48\t\n49\timport yaml\n50\t\n51\tSECTIONS = [(\"Description\", (\"description\",)),\n52\t            (\"Scope\", (\"scope\",)),\n53\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n54\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n55\t\n56\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n57\t\n58\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n59\t           \"repo-onboarding\")\n60\t\n61\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n62\t# way) — parity with the implementation_type_rules judge.\n63\tPARALLEL_PAIRS = {\n64\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n65\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n66\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n67\t}\n68\t\n69\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n70\t\n71\t# An enforcement tool named in a general Implementation epic's TITLE — the\n72\t# signature of a work-type extraction of a shared-surface deliverable.\n73\tENFORCEMENT_TITLE_RE = re.compile(\n74\t    r'\\b(lint(?:er)? rule|ci check|static[- ]analysis|validation harness|'\n75\t    r'enforc\\w*)\\b', re.IGNORECASE)\n76\t\n77\t\n78\tdef read_frontmatter(path):\n79\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n80\t    with open(path, encoding=\"utf-8\") as f:\n81\t        content = f.read()\n82\t    m = FRONTMATTER_RE.match(content)\n83\t    if not m:\n84\t        return {}, content\n85\t    try:\n86\t        data = yaml.safe_load(m.group(1))\n87\t    except yaml.YAMLError:\n88\t        return {}, content\n89\t    if not isinstance(data, dict):\n90\t        return {}, content\n91\t    return data, content[m.end():]\n92\t\n93\t\n94\tdef body_headings(body):\n95\t    heads = []\n96\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n97\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n98\t    return heads\n99\t\n100\t\n101\tdef load_epics(artifacts_dir, strat_id):\n102\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n103\t\n104\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n105\t    \"\"\"\n106\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n107\t    if not os.path.isdir(task_dir):\n108\t        return {}\n109\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n110\t    epics = {}\n111\t    for name in sorted(os.listdir(task_dir)):\n112\t        m = pat.match(name)\n113\t        if not m:\n114\t            continue\n115\t        path = os.path.join(task_dir, name)\n116\t        fm, body = read_frontmatter(path)\n117\t        epics[name[:-3]] = (path, fm, body)\n118\t    return epics\n119\t\n120\t\n121\tdef dependency_closure(start_key, deps):\n122\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n123\t    seen, stack = set(), list(deps.get(start_key, []))\n124\t    while stack:\n125\t        n = stack.pop()\n126\t        if n in seen or n not in deps:\n127\t            continue\n128\t        seen.add(n)\n129\t        stack.extend(deps[n])\n130\t    return seen\n131\t\n132\t\n133\tdef check(strat_id, artifacts_dir, components_path):\n134\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n135\t    probs = []\n136\t    epics = load_epics(artifacts_dir, strat_id)\n137\t    if not epics:\n138\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n139\t                % (strat_id, artifacts_dir)]\n140\t\n141\t    valid_components = set()\n142\t    if os.path.isfile(components_path):\n143\t        with open(components_path, encoding=\"utf-8\") as f:\n144\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n145\t    if not valid_components:\n146\t        probs.append(\"cannot read canonical component list %s — verify the \"\n147\t                     \"path before trusting component names\" % components_path)\n148\t\n149\t    deps, is_branch, is_docs, is_impl, itype, prio, titles, comps = \\\n150\t        {}, {}, {}, {}, {}, {}, {}, {}\n151\t    for key, (path, fm, body) in epics.items():\n152\t        name = key + \".md\"\n153\t        # 1. body sections (contract parity with the artifact judge)\n154\t        heads = body_headings(body)\n155\t        for want, aliases in SECTIONS:\n156\t            if not any(a in h for h in heads for a in aliases):\n157\t                probs.append(\"%s: body missing '%s' section (required \"\n158\t                             \"sections: Description, Scope, Acceptance \"\n159\t                             \"Criteria, HLR Traceability)\" % (name, want))\n160\t        # 2. component vocabulary\n161\t        comp = fm.get(\"component\")\n162\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n163\t                and comp.strip() not in valid_components:\n164\t            probs.append(\"%s: component '%s' is not in %s —